            new[] { "welcome.controller", "Point at Start Tutorial.\nPress the index-finger Trigger to begin.", "ชี้ที่ “เริ่มบทฝึก”\nกด Trigger ด้วยนิ้วชี้เพื่อเริ่ม", "「練習を開始」を指し、\n人差し指でトリガーを押してください。" },
            new[] { "welcome.hand", "Point at Start Tutorial.\nPinch thumb and index finger, then release.", "ชี้ที่ “เริ่มบทฝึก”\nจีบนิ้วโป้งกับนิ้วชี้ แล้วคลาย", "「練習を開始」を指し、\n親指と人差し指をつまんで離します。" },
            new[] { "tutorial.try.teleport.controller", "Hold the thumbstick forward.\nAim the arc at a floor ring, then release.", "ดันก้านนิ้วโป้งไปข้างหน้าค้าง\nเล็งเส้นโค้งที่วงบนพื้น แล้วปล่อย", "スティックを前に倒したまま、\n曲線を床の円に合わせて\n離します。" },
            new[] { "tutorial.try.teleport.hand", "Make an L shape to show the floor ray.\nAim at a floor ring, pinch, then release.", "ทำมือรูปตัว L จนเห็นเส้นชี้พื้น\nเล็งที่วงบนพื้น จีบนิ้ว แล้วคลาย", "手をL字にして床への線を出し、\n床の円に合わせ、\nつまんで離します。" },
            new[] { "tutorial.try.snap.controller", "Push the thumbstick left or right once.", "ดันก้านนิ้วโป้งซ้ายหรือขวาหนึ่งครั้ง", "スティックを左右どちらかへ\n一度倒します。" },
            new[] { "tutorial.try.snap.hand", "Make an L shape; pinch and hold.\nMove your hand left or right, then release.", "ทำมือรูปตัว L แล้วจีบนิ้วค้าง\nเลื่อนมือซ้ายหรือขวา แล้วคลาย", "手をL字にしてつまんだまま、\n左右に動かして離します。" },
            new[] { "tutorial.try.roomscale", "Move your head sideways\nabout 20 cm, slowly.\nStay in your safe area.", "ขยับศีรษะด้านข้างประมาณ 20 ซม.\nขยับช้า ๆ ภายในพื้นที่เล่นที่ปลอดภัย", "頭を横に約20cm動かします。\n安全なエリア内で\nゆっくり行います。" },
            new[] { "tutorial.try.select.controller", "Point at Practice; press and release Trigger.", "ชี้ที่ “ปุ่มฝึก”\nกดแล้วปล่อย Trigger (นิ้วชี้)", "「練習ボタン」を指し、\nトリガー（人差し指）を\n押して離します。" },
            new[] { "tutorial.try.select.hand", "Point at Practice; pinch, then release.", "ชี้ที่ “ปุ่มฝึก”\nจีบนิ้วโป้งกับนิ้วชี้ แล้วคลาย", "「練習ボタン」を指し、\n親指と人差し指を\nつまんで離します。" },
            new[] { "tutorial.try.grab.controller", "Reach for the mug or stone on the table.\nHold the side Grip button.", "ยื่นมือไปที่แก้วหรือก้อนหินบนโต๊ะ\nกด Grip ด้านข้าง (นิ้วกลาง) ค้าง", "机のカップか石に手を近づけ、\nGrip（中指）を押し続けます。" },
            new[] { "tutorial.try.grab.hand", "Reach for the mug or stone on the table.\nClose your hand.", "ยื่นมือไปที่แก้วหรือก้อนหินบนโต๊ะ\nหุบนิ้วเพื่อจับ", "机のカップか石に手を近づけ、\n指を閉じてつかみます。" },
            new[] { "tutorial.try.regrab.controller", "Hold the side Grip button.", "กด Grip ด้านข้างค้าง", "Gripを押し続けます。" },
            new[] { "tutorial.try.regrab.hand", "Close your hand.", "หุบนิ้วเพื่อจับ", "指を閉じます。" },
            new[] { "tutorial.try.move", "Keep holding; lift about 10 cm.", "จับค้างไว้ แล้วยกประมาณ 10 ซม.", "つかんだまま\n約10cm持ち上げます。" },
            new[] { "tutorial.try.rotate", "Keep holding; turn your wrist about 30°.", "จับค้างไว้\nแล้วหมุนข้อมือประมาณ 30 องศา", "つかんだまま\n手首を約30度回します。" },
            new[] { "tutorial.try.release.controller", "Lower it near the table, then release Grip.", "วางลงใกล้โต๊ะ แล้วปล่อย Grip", "机の近くまで下ろし、\nGripを離します。" },
            new[] { "tutorial.try.release.hand", "Lower it near the table, then open your hand.", "วางลงใกล้โต๊ะ แล้วกางนิ้ว", "机の近くまで下ろし、\n指を開きます。" },
            new[] { "tutorial.try.reference", "Select Reference.", "เลือก “เอกสารอ้างอิง”", "「参照資料」を選びます。" },
            new[] { "tutorial.try.restore", "Select the small Reference bar to reopen.", "เลือกแถบเอกสารอ้างอิงเพื่อเปิดกลับ", "小さな参照バーを選んで開きます。" },
            new[] { "tutorial.try.switch", "Select another available format.", "เลือกรูปแบบสื่ออื่นที่เปิดได้", "別の利用可能な形式を選びます。" },
            new[] { "tutorial.try.reposition.controller", "Hold Trigger on the lower handle. Move, then release.", "กด Trigger ค้างที่มือจับล่าง เลื่อนแล้วปล่อย", "下のハンドルでTriggerを押し続け、動かして離します。" },
            new[] { "tutorial.try.reposition.hand", "Pinch and hold the lower handle. Move, then release.", "จีบค้างที่มือจับล่าง เลื่อนแล้วปล่อย", "下のハンドルをつまんだまま動かし、離します。" },
            new[] { "tutorial.try.close", "Select × to close the panel.", "เลือก × เพื่อปิดแผง", "×を選んでパネルを閉じます。" },
            new[] { "tutorial.try.examine", "Select Examine on the module. It only shows information.", "เลือก “ตรวจดู” ที่โมดูล เพื่ออ่านข้อมูลเท่านั้น", "モジュールの「確認」を選びます。情報表示のみです。" },
            new[] { "tutorial.try.insert_wrong", "Practice the blocked direction: hold Grip on the yellow module.\nPoint its cut corner opposite the slot's cut corner, then lower gently until it stops.", "ฝึกด้านที่ใส่ไม่ได้: จับโมดูลสีเหลืองด้วย Grip\nหันมุมบากไปคนละฝั่งกับช่อง ค่อย ๆ ลดลงจนติด ไม่ต้องฝืน", "入らない向きの練習です。黄色のモジュールをGripで持ちます。\n切り欠きをスロットと反対側に向け、ゆっくり下ろして止めます。" },
            new[] { "tutorial.try.insert_wrong.v2", "Now feel the blocked way: pull the module out, turn it half a turn so the cut corner is on the other side, and lower it in.\nIt stops and does not go in. Do not force it.", "ต่อไปลองด้านที่ใส่ไม่ได้: ดึงโมดูลออก หมุนกลับครึ่งรอบให้มุมบากไปอีกฝั่ง แล้วค่อย ๆ ลดลง\nโมดูลจะติด ไม่ลง ไม่ต้องฝืน", "次は入らない向きを確かめます。モジュールを抜き、半回転させて切り欠きを反対側にし、ゆっくり下ろします。\n途中で止まって入りません。無理に押し込まないでください。" },
            new[] { "tutorial.try.insert", "Hold Grip. Match the cut corners, push fully in, then release.", "จับด้วย Grip ให้มุมบากตรงกัน กดจนสุดแล้วปล่อย", "Gripで持ち、切り欠きを合わせ、奥まで入れて離します。" },
            new[] { "tutorial.try.lock", "Put the module back in the way it fits, then close the latch.\nPlaced is not the same as secured.", "ใส่โมดูลกลับด้านที่ใส่ได้ให้เข้าที่ แล้วปิดสลัก\nวางเข้าที่ยังไม่เท่ากับยึดแล้ว", "モジュールを入る向きで差し直し、ラッチを閉じます。\n置いただけでは固定されていません。" },
            new[] { "tutorial.try.lock.v3", "Module in. Grip the latch to close it.", "ใส่แล้ว กด Grip ที่สลักเพื่อปิดล็อก", "挿入できました。Gripでラッチを閉じます。" },
            new[] { "tutorial.try.unlock", "Open the latch, then pull out the module.", "เปิดสลัก แล้วดึงโมดูลออก", "ラッチを開き、モジュールを引き抜きます。" },
            new[] { "tutorial.try.rotate_access", "Grip the front handle. Move your hand in an arc to face the rear screw. Regrip if needed.", "Grip ที่มือจับหน้า พามือเป็นวงให้สกรูด้านหลังหันมา ปล่อยจับใหม่ได้", "手前のハンドルをGripで持ち、手を弧状に動かして奥のねじを手前へ。持ち直せます。" },
            new[] { "tutorial.try.fasten", "Face the screw head. Trigger-grab and turn clockwise. Regrip; progress stays. Release when tight.", "มองหัวตรง ๆ ใช้ Trigger จับ ขันตามเข็ม ปล่อยจับใหม่ได้ ความคืบหน้ายังอยู่ แน่นแล้วปล่อย", "頭を正面から見てTriggerで持ち、時計回りに締めます。持ち直しても進みは残ります。締まったら離します。" },
            new[] { "tutorial.try.loosen", "Face the screw head. Trigger-grab and turn counter-clockwise. Release when fully loose.", "มองหัวตรง ๆ ใช้ Trigger จับ คลายทวนเข็ม คลายสุดแล้วปล่อย", "頭を正面から見てTriggerで持ち、反時計回りに緩めます。緩みきったら離します。" },
            new[] { "tutorial.try.cable_connect", "Trigger the plug head. Push fully into the open socket.", "Trigger จับหัวปลั๊ก เสียบให้สุดช่องว่าง", "Triggerでプラグの頭を持ち、空きソケットの奥まで差します。" },
            new[] { "tutorial.try.cable_disconnect", "Trigger the plug head and pull it from the socket.", "Trigger จับหัวปลั๊ก แล้วดึงออกจากช่อง", "Triggerでプラグの頭を持ち、ソケットから抜きます。" },
            new[] { "tutorial.try.inspect_fail", "Select Inspect to see a practice “not ready” result.", "เลือก “ตรวจผล” เพื่อดูตัวอย่าง “ยังไม่พร้อม”", "「検査」で練習用の「未完了」例を見ます。" },
            // Fixed-UI training order (AI draft, pending human TH/JA review): Inspect 'not ready' comes before anything is installed,
            // and the 'ready' Inspect follows the install steps the trainee has just done.
            new[] { "tutorial.try.inspect_fail.start", "Select Inspect to see a practice “not ready” result.", "เลือก “ตรวจผล” เพื่อดูตัวอย่าง “ยังไม่พร้อม”", "「検査」で練習用の「未完了」例を見ます。" },
            new[] { "tutorial.try.inspect.trainer_ready", "Select Inspect to see a practice “ready” result.", "เลือก “ตรวจผล” เพื่อดูตัวอย่าง “พร้อม”", "「検査」で練習用の「完了」例を見ます。" },
            new[] { "tutorial.try.inspect.trainer", "A different condition: put the module in, close the latch and tighten the screw, then select Inspect to see a ‘ready’ result.", "อีกเงื่อนไขหนึ่ง: ใส่โมดูล ปิดสลัก และขันสกรูให้แน่น แล้วเลือก “ตรวจผล” เพื่อดูตัวอย่างผล ‘พร้อม’", "別の条件の練習: モジュールを入れてラッチを閉じ、ねじを締めてから「検査」を選び、「完了」の結果の例を見ます。" },
            new[] { "tutorial.fact.examine", "Examine", "ตรวจดู", "確認" },
            new[] { "tutorial.fact.insert_wrong", "Wrong way blocked", "ใส่ผิดด้าน: ติด", "逆向きは入らない" },
            new[] { "tutorial.fact.insert", "Insert module", "ใส่โมดูล", "モジュールを入れる" },
            new[] { "tutorial.fact.lock", "Close latch", "ปิดสลัก", "ラッチを閉じる" },
            new[] { "tutorial.fact.unlock", "Unlatch and pull out", "ปลดสลักแล้วดึงออก", "ラッチを開けて抜く" },
            new[] { "tutorial.fact.rotate_access", "Turn the station", "หมุนแท่น", "台を回す" },
            new[] { "tutorial.fact.fasten", "Tighten screw", "ขันสกรู", "ねじを締める" },
            new[] { "tutorial.fact.loosen", "Loosen screw", "คลายสกรู", "ねじを緩める" },
            new[] { "tutorial.fact.cable_connect", "Connect plug", "เสียบปลั๊ก", "プラグを差す" },
            new[] { "tutorial.fact.cable_disconnect", "Disconnect plug", "ถอดปลั๊ก", "プラグを抜く" },
            new[] { "tutorial.fact.inspect_fail", "Example result: not ready", "ตัวอย่างผล: ยังไม่พร้อม", "結果の例: 未完了" },
            new[] { "tutorial.result.trainer.fail", "Practice result: not ready. Something is not installed or secured yet.", "ผลตัวอย่าง: ยังไม่พร้อม มีบางส่วนยังไม่ได้ใส่หรือยังไม่ได้ยึด", "練習の結果: 未完了。まだ取り付けまたは固定されていない部分があります。" },
            new[] { "tutorial.result.trainer.pass", "Practice result: ready.", "ผลตัวอย่าง: พร้อม", "練習の結果: 完了。" },
            new[] { "examine.target.training.module", "Training module", "โมดูลฝึก", "練習モジュール" },
            new[] { "examine.info.training.module", "Keyed: the cut corner must match the slot. Held by a latch.", "มีบากกันใส่ผิดด้าน: มุมบากต้องตรงช่อง ยึดด้วยสลัก", "向き合わせあり: 切り欠きの角をスロットに合わせます。ラッチで固定します。" },
            new[] { "tutorial.try.inspect", "Select Inspect.\nNo repair is needed in practice.", "เลือก “ตรวจผล”\nบทฝึกนี้ไม่ต้องซ่อมชิ้นส่วน", "「検査」を選びます。\n練習では修理は不要です。" },
            new[] { "tutorial.movement", "Movement", "เคลื่อนที่", "移動" },
            new[] { "tutorial.movement.body", "Hold the teleport stick toward a floor marker, aim at a valid circle, then release to move. Try snap turning afterwards.", "ดันก้านโยกเทเลพอร์ตค้าง เล็งวงกลมบนพื้นที่ไปได้ แล้วปล่อยก้านเพื่อย้ายตำแหน่ง\nจากนั้นลองหมุนมุมมองทีละจังหวะ", "移動用スティックを倒したまま\n床の丸い目印を狙い、離すと移動します。\nその後、スナップ回転を試してください。" },
            new[] { "tutorial.movement.helper", "Aim at a floor teleport circle and release the stick to move.", "เล็งวงกลมเทเลพอร์ตบนพื้น แล้วปล่อยก้านโยกเพื่อย้ายตำแหน่ง", "床の丸い移動先を狙い、スティックを離して移動してください。" },
            new[] { "tutorial.select", "Point & Select", "ชี้และเลือก", "指して選択" },
            new[] { "tutorial.select.body", "Point at the practice button and select it.", "ชี้ที่ปุ่มฝึก แล้วเลือก", "練習ボタンを指して選んでください。" },
            new[] { "tutorial.select.helper", "Point at the practice button and select it.", "ชี้ที่ปุ่มฝึก แล้วเลือก", "練習ボタンを指して選んでください。" },
            new[] { "tutorial.handling", "Grab / Rotate / Release", "จับ / หมุน / ปล่อย", "つかむ / 回す / 放す" },
            new[] { "tutorial.handling.body", "Reach close, lift, rotate, then release. On Touch, hold the side Grip button to grab.", "เข้าใกล้วัตถุ ยก หมุน แล้วปล่อย (Touch: กด Grip ด้านข้างค้างไว้เพื่อจับ)", "手を近づけてつかみ、持ち上げ、回して放します。Touchでは側面のGripボタンを押し続けます。" },
            new[] { "tutorial.handling.helper", "Move the object while holding it.", "จับวัตถุค้างไว้ แล้วขยับมือเพื่อย้าย", "物体をつかんだまま、手を動かしてください。" },
            new[] { "tutorial.reference", "Reference", "เอกสารอ้างอิง", "参照資料" },
            new[] { "tutorial.reference.body", "Open Reference.", "เปิดเอกสารอ้างอิง", "参照資料を開いてください。" },
            new[] { "tutorial.reference.helper", "Grab the handle below the panel to move it.", "จับแถบใต้แผงเพื่อย้าย", "パネル下のハンドルをつかんで動かしてください。" },
            new[] { "tutorial.inspect", "Inspect", "ตรวจผล", "検査" },
            new[] { "tutorial.inspect.body", "Use Inspect to check the practice object.", "เลือก “ตรวจผล” เพื่อตรวจวัตถุฝึก", "「検査」で練習用の物体を検査してください。" },
            new[] { "tutorial.inspect.helper", "Inspect checks the current task state.", "“ตรวจผล” ใช้ตรวจสถานะปัจจุบันของงาน", "「検査」で課題の現在の状態を調べます。" },
            new[] { "tutorial.helper", "Training Helper", "ผู้ช่วยฝึก", "練習ヘルパー" },
            // Participant titles carry the position in the session, not the counterbalanced A/B label.
            new[] { "task.progress", "Task {0} of 2", "งานที่ {0} จาก 2", "課題 {0} / 2" },
            new[] { "task.A.title", "Build the W2 PC", "ประกอบคอม W2", "W2のPCを組み立てる" },
            new[] { "task.A.body", "Build to W2 requirements, then Inspect.\nPower is isolated. Keep the CPU, cooler and PSU fitted.", "ประกอบคอมตาม W2 แล้วตรวจผล\nแยกไฟแล้ว ไม่ถอด CPU/ชุดระบายความร้อน/PSU", "W2の要件に合わせて組み立て、「検査」。\n電源は切り離し済み。CPU・クーラー・PSUは外さない。" },
            new[] { "task.B.title", "Repair fan F2", "ซ่อมพัดลม F2", "扇風機F2を修理する" },
            new[] { "task.B.body", "The fan vibrates or knocks. Repair it, then Inspect.\nKeep power isolated. Do not open the motor or circuit.", "พัดลมสั่นหรือมีเสียงผิดปกติ ซ่อมแล้วตรวจผล\nแยกไฟไว้ ไม่เปิดมอเตอร์หรือวงจร", "扇風機に振動・異音があります。修理後に「検査」。\n電源は切り離したまま。モーター・電気回路は開けない。" },
            // The compact card shows goal and safety. Details retains every task.X.body paragraph. Translation review is pending.
            new[] { "task.A.summary", "See Reference for W2 requirements. Build, then Inspect.\nPower is isolated. Keep the CPU, cooler and PSU fitted.", "ดูข้อกำหนด W2 ในเอกสาร แล้วประกอบและตรวจผล\nแยกไฟแล้ว ไม่ถอด CPU/ชุดระบายความร้อน/PSU", "W2の要件は参照資料へ。組み立てて「検査」。\n電源は切り離し済み。CPU・クーラー・PSUは外さない。" },
            new[] { "task.B.summary", "The fan vibrates or knocks. Repair it, then Inspect.\nSee Reference. Keep power isolated; do not open motor/circuit.", "พัดลมสั่นหรือมีเสียงผิดปกติ ซ่อมแล้วตรวจผล\nดูเอกสาร • แยกไฟไว้ • ไม่เปิดมอเตอร์/วงจร", "扇風機に振動・異音があります。修理後に「検査」。\n参照資料へ。電源を切り離し、モーター・電気回路は開けない。" },
